import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2024Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2024Q1 Ceph社区季度进展报告","date":"2024-03-01T00:00:00.000Z","updated":"2024-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/2024Q1_Ceph社区季度总结.md","filePath":"posts/2024/2024Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2024/2024Q1_Ceph社区季度总结.md"};function h(n,e,s,p,l,_){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-社区-2024q1-季度进展报告" tabindex="-1">Ceph 社区 2024Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2024q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2024Q1 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的讨论高度集中在以下几个技术方向：</p><p><strong>RGW 重构与通知系统改造</strong> RGW 重构会议贯穿整个季度（1月至3月），核心议题是 SNS/QS 风格的 Topic 和通知机制的重新设计。涉及 Topic 授权、持久化通知的 TTL/Max Retry 配置、多站点元数据同步一致性，以及通知迁移策略。详见 <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-03.html">Ceph RGW Refactoring Meeting 2024-01-03</a>)、<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-24.html">Ceph RGW Refactoring Meeting 2024-01-24</a>)、<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.html">Ceph RGW Refactoring Meeting 2024-01-31</a>)。</p><p><strong>Squid 版本发布准备</strong> 代码冻结计划、功能卡点确认、分支管理策略是本季度反复出现的话题，多个功能（端到端追踪、IAM 账户、对象完整性）被列为 Squid 版本的阻塞项或目标特性。</p><p><strong>Crimson/Seastar 架构演进</strong> Crimson OSD 的代码结构、与经典 OSD 的差异、基于 Seastar 框架的异步编程模型是专项代码分析会议的核心内容。详见 <a href="/VideoSummary/posts/2024/Ceph_Code_Walkthroughs_-_Crimson.html">Ceph Code Walkthroughs - Crimson</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="rgw-通知系统" tabindex="-1">RGW 通知系统 <a class="header-anchor" href="#rgw-通知系统" aria-label="Permalink to &quot;RGW 通知系统&quot;">​</a></h3><ul><li><strong>持久化通知 TTL/Max Retry</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.html">Ceph RGW Refactoring Meeting 2024-01-31</a>) 中确定了通过配置选项支持用户和管理员分别设置事件生存时间与最大重试次数，解决消息代理宕机时队列无限增长的问题。</li><li><strong>非持久化通知改进</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-03.html">Ceph RGW Refactoring Meeting 2024-01-03</a>) 讨论了消息代理不可用时应及时向客户端返回错误，而非静默失败。</li><li><strong>Topic 授权机制</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-24.html">Ceph RGW Refactoring Meeting 2024-01-24</a>) 引入全局配置参数控制策略检查行为，解决任意用户可覆盖他人 Topic 的安全漏洞，同时保持向后兼容性。</li><li><strong>Redis 作为消息队列</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.html">Ceph RGW Refactoring Meeting 2024-03-06</a>) 提出使用 Redis（基于 Boost Redis 客户端）替换现有持久化通知系统，处于技术探讨阶段。</li></ul><h3 id="nvme-of-tcp-gateway" tabindex="-1">NVMe-oF TCP Gateway <a class="header-anchor" href="#nvme-of-tcp-gateway" aria-label="Permalink to &quot;NVMe-oF TCP Gateway&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-02-07.html">Ceph Developer Monthly 2024-02-07</a>) 中介绍了 NVMe-oF 在 Ceph 中的高可用性方案，包括 Gateway Group 概念和自动故障转移机制，目标是在未来版本中达到生产就绪状态。</p><h3 id="iam-sts-账户功能" tabindex="-1">IAM/STS 账户功能 <a class="header-anchor" href="#iam-sts-账户功能" aria-label="Permalink to &quot;IAM/STS 账户功能&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.html">Ceph RGW Refactoring Meeting 2024-02-14</a>) 中账户功能实现基本完成，进入代码审查阶段。同时讨论了 IAM 策略限制（策略长度、角色关联策略数量等），计划对齐 AWS 行为并建立相应约束。</p><h3 id="对象完整性与多部分上传" tabindex="-1">对象完整性与多部分上传 <a class="header-anchor" href="#对象完整性与多部分上传" aria-label="Permalink to &quot;对象完整性与多部分上传&quot;">​</a></h3><p>RGW 对象完整性功能（Object Integrity）正在开发中，重点覆盖 multipart uploads 的 API 校验，计划在 Squid 代码冻结前完成。</p><h3 id="端到端追踪-end-to-end-tracing" tabindex="-1">端到端追踪（End-to-End Tracing） <a class="header-anchor" href="#端到端追踪-end-to-end-tracing" aria-label="Permalink to &quot;端到端追踪（End-to-End Tracing）&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-02-07.html">Ceph Developer Monthly 2024-02-07</a>) 中该功能被确认为 Squid 版本的阻塞项，需要完成测试结果审查后方可放行。</p><h3 id="crimson-osd-异步架构" tabindex="-1">Crimson OSD 异步架构 <a class="header-anchor" href="#crimson-osd-异步架构" aria-label="Permalink to &quot;Crimson OSD 异步架构&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Code_Walkthroughs_-_Crimson.html">Ceph Code Walkthroughs - Crimson</a>) 深入分析了 Crimson 与经典 OSD 的代码差异：Crimson 基于 Seastar 框架，使用 Futures + Continuation（C++ Lambda）替代同步阻塞模型，客户端请求管道包含地图等待、活动等待等多个阶段，错误处理通过 <code>erator</code> 机制处理非严重错误。</p><h3 id="多站点复制头" tabindex="-1">多站点复制头 <a class="header-anchor" href="#多站点复制头" aria-label="Permalink to &quot;多站点复制头&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.html">Ceph RGW Refactoring Meeting 2024-02-14</a>) 引入新的复制头 <code>X-Replicated-At</code>，用于多站点负载测试场景，计划作为 Squid 版本的一部分发布。</p><h3 id="s3-对象重复数据检测工具" tabindex="-1">S3 对象重复数据检测工具 <a class="header-anchor" href="#s3-对象重复数据检测工具" aria-label="Permalink to &quot;S3 对象重复数据检测工具&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.html">Ceph RGW Refactoring Meeting 2024-03-06</a>) 中 Gabriel 开发了一个检测 S3 对象级别重复数据（DDoP）的工具，部分集群中发现高达 25% 的重复率，社区鼓励广泛测试。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p>| 事项 | 决策内容 | 来源 | |------|------| | Squid 代码冻结 | 原计划 1 月底，推迟一周至 2 月初执行 | <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.html">2024-01-31</a>) | | Topic 迁移策略 | 启动时执行 Topic 迁移；通知迁移采用懒惰迁移（访问时迁移），在元数据主站点执行 | <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-24.html">2024-01-24</a>) | | 持久化通知配置 | 通过配置选项支持 TTL 和 Max Retry，用户与管理员均可配置 | <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.html">2024-01-31</a>) | | Monitor 网络 Ping 统计 | 批准移除 monitor manager 中Network ping stats 输出，下一主要版本生效，更新发布说明 | <a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-02-07.html">2024-02-07</a>) | | TC 版本兼容性 | 在 SEF spec 文件中拒绝 TC 2.8.x 所有次要版本，规避已知崩溃问题 | <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.html">2024-03-06</a>) | | IAM 策略限制跟踪 | 创建 Tracker 监控 IAM 相关元数据限制问题，为未来对齐 AWS 行为做准备 | <a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.html">2024-02-14</a>) | | 磁带存储功能请求 | 创建 Tracker 票证跟踪磁带作为对象存储类（类 AWS Glacier）的功能需求 | <a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.html">2024-01-18</a>) |</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>月度开发者会议</strong> 2 月 7 日的 <a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-02-07.html">Ceph Developer Monthly</a>) 涵盖了 NVMe-oF 高可用方案介绍、端到端追踪 PR 审查请求、Monitor 统计输出变更等多个议题，体现了社区在多个技术方向的并行推进。</p><p><strong>用户与开发者联合会议</strong><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.html">Ceph User + Dev Monthly 2024-01-18</a>) 中，国家太阳能天文台（DEIS 项目）的操作员 Joel Davido 提出了磁带存储集成需求，展示了科学计算场景对 Ceph 长期归档能力的实际诉求，推动了相关功能讨论进入社区视野。</p><p><strong>RGW 专项重构会议</strong> 本季度 RGW 重构会议密度较高（1 月 3 日、1 月 24 日、1 月 31 日、2 月 14 日、3 月 6 日），产品团队（Nicholas 等）直接参与技术讨论，体现了 RGW 功能商业化落地的迫切需求。</p><p><strong>Google Summer of Code</strong><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.html">Ceph RGW Refactoring Meeting 2024-03-06</a>) 中提及了 Zipper 相关的 GSoC 项目想法征集，鼓励社区成员参与。</p><p><strong>代码走查活动</strong> Crimson 代码走查会议面向社区开放，帮助开发者理解 Seastar 异步编程模型与经典 OSD 的差异，降低新贡献者的上手门槛。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2024Q 将重点推进以下方向：</p><ol><li><p><strong>Squid 版本发布</strong>：代码冻结已执行，Q2 将进入 RC 测试和正式发布阶段，端到端追踪、IAM 账户、对象完整性等功能将随版本落地。</p></li><li><p><strong>RGW 通知系统完善</strong>：Topic 授权、持久化通知 TTL/Max Retry、多站点元数据一致性等 PR 将陆续完成审查合并；Redis 消息队列方案可能进入原型验证阶段。</p></li><li><p><strong>NVMe-oF 高可用生产就绪</strong>：Gateway Group 和自动故障转移机制将继续完善，目标是在后续版本中达到生产可用状态。</p></li><li><p><strong>IAM/STS 功能扩展</strong>：账户功能代码审查完成后，IAM 策略限制对齐 AWS 行为的工作将提上日程。</p></li><li><p><strong>Crimson OSD 持续演进</strong>：基于本季度代码走查的反馈，Crimson 的错误处理和依赖条件管理逻辑将继续优化。</p></li><li><p><strong>磁带存储集成探索</strong>：功能 Tracker 已建立，Q2 可能开始分解子任务，探索 S3 生命周期管理与 Glacier API 集成的具体实现路径。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2024/Ceph_Code_Walkthroughs_-_Crimson.html">Ceph Code Walkthroughs: Crimson</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-02-07.html">Ceph Developer Monthly 2024-02-07</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-03.html">Ceph RGW Refactoring Meeting 2024-01-03</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-24.html">Ceph RGW Refactoring Meeting 2024-01-24</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.html">Ceph RGW Refactoring Meeting 2024-01-31</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.html">Ceph RGW Refactoring Meeting 2024-02-14</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.html">Ceph RGW Refactoring Meeting 2024-03-06</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.html">Ceph User + Dev Monthly 2024-01-18</a>)</li></ul>',42)])])}const d=a(i,[["render",h]]);export{g as __pageData,d as default};
